  p_Description_cee39c66457b := 'MiniMax''s agent-focused Flash-tier model, generally available October 19, 2026 after a September 27 preview (`MiniMax-M3.1-Flash-Preview`). Sparse-attention MoE in the M3 line, 1M token context with flat pricing across the whole window and no long-context step-up — unlike MiniMax-M3, which doubles above 512K. Thinking is always on with effort levels low through max. Text, image and video input. MiniMax reports roughly one-third the cost and about 3x the speed of M3 on agentic workloads. Priced at $0.15/1M input, $0.60/1M output, $0.015/1M cached input. Open weights were announced for release shortly after launch; reports as of 2026-10-26 conflict on whether they have been published. MaxOutputTokens mirrors MiniMax-M3''s 131,072 — third-party listings disagree (128K on some, 512K on others) and platform.minimax.io was not reachable from this environment to settle it.';
