    widthHint?: ''narrow'' | ''medium'' | ''wide'' | ''full'' | ''auto'';  // Optional width hint for the input field.
}

type FormQuestionType =
    | TextQuestionType
    | NumberQuestionType
    | DateQuestionType
    | ChoiceQuestionType
    | SliderQuestionType
    | DateRangeQuestionType
    | TimeQuestionType;

interface TextQuestionType {
    type: ''text'' | ''textarea'' | ''email'';  // Type of text input:
