DO $mj$
DECLARE
  p_ID_cdafa4b8a4a2 UUID;
  p_TemplateID_cdafa4b8a4a2 UUID;
  p_Name_cdafa4b8a4a2 VARCHAR(255);
  p_Description_cdafa4b8a4a2 TEXT;
