  p_Name_631b6c0a540e := 'Content Pipeline — Sync';
  p_Description_631b6c0a540e := 'Exhaustively walks each selected Content Source (ignoring LastDiscoveredAt), reconciles top-level items that were removed from the source by marking them DeleteStatus = ''Pending'' for the Delete stage, and stamps both LastDiscoveredAt and LastSyncedAt on completion. Selects sources by LastSyncedAt (never by ForceDiscovery, which belongs to Discover); to force a sync on a source, set its LastSyncedAt back or to NULL. Unscheduled by default.';
  p_EntityID_631b6c0a540e := (
    SELECT
      "ID"
    FROM
      __mj."Entity"
    WHERE
      "Name" = 'MJ: Content Sources'
  );
  p_Status_631b6c0a540e := 'Active';
  p_WorkType_631b6c0a540e := 'Pipeline Stage';
  p_ScopeType_631b6c0a540e := 'Filter';
  p_ScopeFilter_631b6c0a540e := 'LastSyncedAt IS NULL OR LastSyncedAt < DATEADD(day, -30, NOW())';
  p_OnChangeEnabled_631b6c0a540e := FALSE;
  p_ScheduleEnabled_631b6c0a540e := FALSE;
  p_Timezone_631b6c0a540e := 'UTC';
  p_OnDemandEnabled_631b6c0a540e := TRUE;
  p_SkipUnchanged_631b6c0a540e := FALSE;
  p_WatermarkStrategy_631b6c0a540e := 'Checksum';
  p_BatchSize_631b6c0a540e := 25;
  p_MaxConcurrency_631b6c0a540e := 1;
  p_Configuration_631b6c0a540e := '{
  "Stages": [
    "Discover"
  ],
  "Options": {
    "Mode": "Sync",
    "Tuning": {
      "MaxSyncRemovalShare": 0.5
    }
  }
}';
  IF NOT EXISTS (SELECT 1 FROM __mj."RecordProcess" WHERE "ID" = p_ID_631b6c0a540e) THEN
    IF EXISTS (
      SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
       WHERE n.nspname = '__mj' AND p.proname = 'spCreateRecordProcess'
         AND p.pronargs = 1 AND p.proargtypes[0] = 'jsonb'::regtype
    ) THEN
